def calculate_average(numbers):
    """Calculate the average of a list of numbers."""
    if not numbers:
        return 0
    return sum(numbers) / len(numbers)

def filter_non_empty(items):
    """Filter out None and empty items from a list."""
    return [item for item in items if item is not None and item != '']

def process_user_data(user_data):
    """Process user data and return cleaned information."""
    cleaned = {
        'username': user_data.get('username', '').strip(),
        'email': user_data.get('email', '').strip().lower(),
        'age': user_data.get('age', 0)
    }
    return cleaned

def validate_input(value, min_val=0, max_val=100):
    """Validate that a value is within a given range."""
    if not isinstance(value, (int, float)):
        return False
    return min_val <= value <= max_val

def complex_nested(x, y, z):
    if x > 0:
        if y > 0:
            if z > 0:
                return True
            else:
                return False
        else:
            return False
    else:
        return False

def deep_nesting(a, b, c, d, e):
    if a > 0:
        if b > 0:
            if c > 0:
                if d > 0:
                    if e > 0:
                        return "All positive"
                    else:
                        return "e not positive"
                else:
                    return "d not positive"
            else:
                return "c not positive"
        else:
            return "b not positive"
    else:
        return "a not positive"

def recursive_function(n):
    if n > 0:
        return recursive_function(n-1) + recursive_function(n-2)
    return n

def many_conditions(x):
    if x < 0:
        return "negative"
    elif x == 0:
        return "zero"
    elif x > 0 and x < 10:
        return "small"
    elif x >= 10 and x < 20:
        return "medium"
    elif x >= 20 and x < 50:
        return "large"
    else:
        return "very large"

def check_positive_values(*args):
    """Check if all values are positive."""
    return all(val > 0 for val in args)

def validate_positive(value):
    """Validate that a value is positive."""
