def get_value_category(x):
    """Categorize a numeric value."""
    if x < 0:
        return "negative"
    if x == 0:
        return "zero"
    if x < 10:
        return "small"
    if x < 20:
        return "medium"
    if x < 50:
        return "large"
    return "very large"

def fibonacci(n, memo={}):
    """Calculate Fibonacci number with memoization."""
    if n in memo:
        return memo[n]
    if n <= 1:
        return n
    memo[n] = fibonacci(n-1, memo) + fibonacci(n-2, memo)
    return memo[n]

def process_items(items):
    """Process items with clear logic and early returns."""
    if not items:
        return []

    result = []
    for item in items:
        if item is None:
            continue
        if not isinstance(item, str):
            continue
        if not item.strip():
            continue
        result.append(item.strip().lower())

    return result

